//    Effects/Water/Water Code / layer 'Layer 2' / frame 2
void frame_802_1(Activation& scope) {
    stop();
    // Ocean - Jim Bumgardner
    scope["kNbrPts"] = scope["polygons"];
    scope["SW"] = scope["WaterLength"];
    scope["SH"] = 0;
    MovieClip["prototype"]["makeWave"] = scope.function([](Activation& scope) -> Value {
        Value deep = scope.args[0];
        Value clr = scope.args[1];
        Value jit = scope.args[2];
        Value turbProb = scope.args[3];
        Value i;
        //if (_root.PauseGame == false && _root.playpause == false && Math.abs(_root.Course.Char._y-(_y+_root.Course.FrontGFX._y))<1000) {
        scope.self["pts"] = arr({});
        scope.self["springs"] = arr({});
        scope.self["clr"] = clr;
        scope.self["jit"] = jit;
        scope.self["turbProb"] = turbProb;
        scope.self["deep"] = deep;
        scope.self["stiffK"] = scope["waterstength"];
        scope.self["kDamp"] = 0.85;
        Value segLen = (scope["SW"] + 100) / scope["kNbrPts"];
        for (i = 0; i < scope["kNbrPts"]; ++i) {
            scope.self["pts"][i] = obj({{"x", -50 + i * segLen}, {"y", 0}, {"fx", 0}, {"fy", 0}, {"vx", 0}, {"vy", 0}, {"restLen", 0.5 * segLen}, {"jy", 0}});
        }
        //}
        return undefined;
    });
    MovieClip["prototype"]["simWave"] = scope.function([](Activation& scope) -> Value {
        Value i, pt1, pt2, dx, dy, dist, f1, spr_fx, spr_fy;
        if (_root["PauseGame"] == false && Math["abs"](_root["Course"]["Char"]["_y"] - (scope["_y"] + _root["Course"]["FrontGFX"]["_y"])) < 1000) {
            // Initialize forces with some noise
            for (i = 0; i < scope.self["pts"]["length"]; ++i) {
                scope.self["pts"][i]["fy"] += Math["random"]() * (scope["randomwave"] * 2) - scope["randomwave"];
                scope.self["pts"][i]["fx"] = 0;
                if (Math["random"]() < scope.self["turbProb"]) {
                } else {
                    scope.self["pts"][i]["fy"] = 0;
                }
            }
            //
            if (scope["graphics"] == false) {
                if (Math["abs"](_root["Course"]["Char"]["yspeed"]) > 5 && Math["abs"](_root["Course"]["Char"]["_y"] - (scope["_y"] + _root["Course"]["FrontGFX"]["_y"])) < 20) {
                    if (scope["rot"] == undefined || scope["rot"] == 0 || scope["rot"] == 180) {
                        scope["X"] = _root["Course"]["Char"]["_x"] - (scope["_x"] + _root["Course"]["FrontGFX"]["_x"]) + _root["Course"]["Char"]["xspeed"];
                    } else {
                        scope["X"] = _root["Course"]["Char"]["_y"] - (scope["_y"] + _root["Course"]["FrontGFX"]["_y"]) + _root["Course"]["Char"]["yspeed"];
                    }
                    scope["marioI"] = Math["round"](((scope["X"]) / scope["SW"] * (scope["kNbrPts"])));
                    if (_root["Course"]["Char"]["yspeed"] > 0) {
                        scope.self["pts"][scope["marioI"]]["fy"] = _root["Course"]["Char"]["yspeed"] / 2;
                    } else {
                        scope.self["pts"][scope["marioI"]]["fy"] = _root["Course"]["Char"]["yspeed"] / 3;
                    }
                    scope.self["pts"][scope["marioI"]]["fx"] += _root["Course"]["Char"]["xspeed"] / 5;
                    for (i = 1; i < 3; ++i) {
                        if (scope["rot"] == undefined || scope["rot"] == 0) {
                            scope.self["pts"][scope["mouseI"] + i]["fy"] -= (_root["Course"]["Char"]["yspeed"] / 15) / i;
                            scope.self["pts"][scope["mouseI"] - i]["fy"] -= (_root["Course"]["Char"]["yspeed"] / 15) / i;
                            scope.self["pts"][scope["marioI"]]["fx"] += (_root["Course"]["Char"]["xspeed"] / 10) / i;
                        } else if (scope["rot"] == 90) {
                            scope.self["pts"][scope["mouseI"] + i]["fy"] -= (_root["Course"]["Char"]["xspeed"] / 15) / i;
                            scope.self["pts"][scope["mouseI"] - i]["fy"] -= (_root["Course"]["Char"]["xspeed"] / 15) / i;
                            scope.self["pts"][scope["marioI"]]["fx"] += (_root["Course"]["Char"]["yspeed"] / 10) / i;
                        } else if (scope["rot"] == -90) {
                            scope.self["pts"][scope["mouseI"] + i]["fy"] += (_root["Course"]["Char"]["xspeed"] / 15) / i;
                            scope.self["pts"][scope["mouseI"] - i]["fy"] += (_root["Course"]["Char"]["xspeed"] / 15) / i;
                            scope.self["pts"][scope["marioI"]]["fx"] -= (_root["Course"]["Char"]["yspeed"] / 10) / i;
                        } else {
                            scope.self["pts"][scope["mouseI"] + i]["fy"] += (_root["Course"]["Char"]["yspeed"] / 15) / i;
                            scope.self["pts"][scope["mouseI"] - i]["fy"] += (_root["Course"]["Char"]["yspeed"] / 15) / i;
                            scope.self["pts"][scope["marioI"]]["fx"] -= (_root["Course"]["Char"]["xspeed"] / 10) / i;
                            // rot = 180
                        }
                    }
                }
            }
            // compute spring forces
            for (i = 0; i < scope.self["pts"]["length"] - 1; ++i) {
                pt1 = scope.self["pts"][i];
                pt2 = scope.self["pts"][i + 1];
                dx = pt2["x"] - pt1["x"];
                dy = pt2["y"] - pt1["y"];
                dist = Math["sqrt"](dx * dx + dy * dy);
                f1 = scope.self["stiffK"] * (dist - pt1["restLen"]);
                spr_fx = f1 * dx / dist;
                spr_fy = f1 * dy / dist;
                if (i != 0) {
                    pt1["fx"] += spr_fx;
                    pt1["fy"] += spr_fy;
                }
                if (i != scope.self["pts"]["length"] - 2) {
                    pt2["fx"] -= spr_fx;
                    pt2["fy"] -= spr_fy;
                }
            }
            scope.self["clear"]();
            scope["r"] = Math["floor"](scope["redcolor"]);
            scope["g"] = Math["floor"](scope["greencolor"]);
            scope["b"] = Math["floor"](scope["bluecolor"]);
            scope.self["clr"] = (scope["r"] << 16 | scope["g"] << 8 | scope["b"]);
            scope.self["beginFill"](scope.self["clr"], scope["alpha"]);
            scope.self["moveTo"](scope.self["pts"][0]["x"], scope.self["pts"][0]["y"]);
            for (i = 1; i < scope.self["pts"]["length"] - 1; ++i) {
                scope["pt"] = scope.self["pts"][i];
                scope["pt"]["vx"] *= scope.self["kDamp"];
                scope["pt"]["vy"] *= scope.self["kDamp"];
                scope["pt"]["vx"] += scope["pt"]["fx"];
                scope["pt"]["vy"] += scope["pt"]["fy"];
                scope["pt"]["x"] += scope["pt"]["vx"];
                scope["pt"]["y"] += scope["pt"]["vy"];
                scope.self["lineTo"](scope["pt"]["x"], scope["pt"]["y"]);
            }
            i = scope.self["pts"]["length"] - 1;
            scope.self["lineTo"](scope.self["pts"][i]["x"], scope.self["pts"][i]["y"]);
            //this.lineTo(this.pts[i].x, this.deep);
            //this.lineTo(this.pts[0].x, this.deep);
            scope.self["lineTo"](scope.self["pts"][i]["x"], scope["WaterDeepness"]);
            scope.self["lineTo"](scope.self["pts"][0]["x"], scope["WaterDeepness"]);
            scope.self["lineTo"](scope.self["pts"][0]["x"], scope.self["pts"][0]["y"]);
            scope.self["endFill"]();
        }
        return undefined;
    });
    scope.var("d") = 0;
    scope.var("vd") = 4;
    scope["kNbrLines"] = 1;
    for (scope.var("i") = 1; scope["i"] < scope["kNbrLines"] + 1; ++scope["i"]) {
        scope.var("r") = scope["i"] / (scope["kNbrLines"] - 1);
        scope.var("ir") = 1 - scope["r"];
        scope.var("mc") = scope.self["createEmptyMovieClip"]("mc" + scope["i"], scope["kNbrLines"] * 2 + 1 - scope["i"] * 2);
        scope["mc"]["_x"] = 0;
        scope["mc"]["_y"] = scope["SH"] / 2 - scope["d"];
        scope.var("deep");
        if (scope["i"] == 0) {
            scope["deep"] = scope["SH"] / 2;
        } else {
            scope["deep"] = scope["d"] * 2;
        }
        scope["mc"]["makeWave"](scope["deep"], scope["mergeColor"](0x333747, 0xD6D5D9, scope["r"] * 0.9), 0.1 + 1 * scope["ir"] * scope["ir"], 0.1);
        scope["mc"]["onEnterFrame"] = scope["mc"]["simWave"];
        scope["d"] += scope["vd"];
        scope["vd"] /= 2;
    }
    scope["SS"] = 10;
    scope.var("mc") = "";
    scope["mc"]["cy"] = scope["SH"] / 2.8;
    scope["mc"]["_x"] = -scope["SW"];
    scope["mc"]["_y"] = scope["SH"] / 4;
    //
}

